-- name: InsertScheduleRun :one
INSERT INTO schedule_runs (team_id, schedule_id, app_id, trigger, status, started_at, finished_at, duration_ms, error)
VALUES (sqlc.arg('team_id'), sqlc.arg('schedule_id'), sqlc.arg('app_id'), sqlc.arg('trigger'), sqlc.arg('status'),
    sqlc.arg('started_at')::timestamptz, sqlc.narg('finished_at'), sqlc.narg('duration_ms'), sqlc.arg('error'))
RETURNING *;

-- name: SetScheduleRunOperation :exec
UPDATE schedule_runs SET operation_id = sqlc.arg('operation_id')::text, updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: ActiveRunOfSchedule :one
-- The run of a schedule that is still going (queued or running), if any.
SELECT * FROM schedule_runs
WHERE schedule_id = sqlc.arg('schedule_id') AND team_id = sqlc.arg('team_id') AND status IN ('queued', 'running')
ORDER BY started_at DESC LIMIT 1;

-- name: PruneScheduleRuns :execrows
-- Keep the newest `keep` runs of a schedule (never dropping one that is still going).
DELETE FROM schedule_runs d
WHERE d.schedule_id = sqlc.arg('schedule_id') AND d.team_id = sqlc.arg('team_id') AND d.status NOT IN ('queued', 'running')
  AND d.id IN (
    SELECT r.id FROM schedule_runs r
    WHERE r.schedule_id = sqlc.arg('schedule_id') AND r.team_id = sqlc.arg('team_id')
    ORDER BY r.started_at DESC, r.id DESC
    OFFSET sqlc.arg('keep'));

-- name: MarkScheduleRunRunning :execrows
UPDATE schedule_runs SET status = 'running', updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND status = 'queued';

-- name: FinishScheduleRun :one
-- Once: only a run that is still going can finish (no rows = it was finished already).
UPDATE schedule_runs SET status = sqlc.arg('status'), exit_code = sqlc.narg('exit_code'), finished_at = sqlc.arg('finished_at')::timestamptz,
    duration_ms = sqlc.arg('duration_ms')::bigint, output = sqlc.arg('output'), error = sqlc.arg('error'), updated_at = now()
WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id') AND status IN ('queued', 'running')
RETURNING *;

-- name: ScheduleRunOfSchedule :one
SELECT * FROM schedule_runs WHERE id = sqlc.arg('id') AND schedule_id = sqlc.arg('schedule_id') AND team_id = sqlc.arg('team_id');

-- name: LatestRunsOfApp :many
-- The newest run of each of an app's schedules.
SELECT DISTINCT ON (schedule_id) * FROM schedule_runs
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id')
ORDER BY schedule_id, started_at DESC, id DESC;

-- name: LatestRunOfSchedule :one
SELECT * FROM schedule_runs WHERE schedule_id = sqlc.arg('schedule_id') AND team_id = sqlc.arg('team_id')
ORDER BY started_at DESC, id DESC LIMIT 1;

-- name: ScheduleRunFeed :many
-- Keyset page of the runs of a schedule, newest first.
SELECT * FROM schedule_runs
WHERE schedule_id = sqlc.arg('schedule_id') AND team_id = sqlc.arg('team_id')
  AND (sqlc.narg('before_at')::timestamptz IS NULL OR (started_at, id) < (sqlc.narg('before_at')::timestamptz, sqlc.arg('before_id')::text))
ORDER BY started_at DESC, id DESC
LIMIT sqlc.arg('limit_rows');

-- name: StrandedScheduleRuns :many
-- Scheduler (system scope): runs that are still going although their operation has finished (the
-- watcher that would have copied the outcome died with its process) or is gone.
SELECT r.* FROM schedule_runs r
LEFT JOIN operations o ON o.id = r.operation_id
WHERE r.status IN ('queued', 'running')
  AND (o.id IS NULL OR o.status IN ('ok', 'failed', 'timeout'))
ORDER BY r.started_at
LIMIT sqlc.arg('lim');
